let librarySignature='';
let traktAuthTimer=null;
let traktSearchTimer=null,traktSearchRequest=0;
let activityTimer=null,currentReleaseTitle='',currentReleaseMedia=null,currentTraktDetail=null,currentTargetEpisode=null;
