const toast = (message) => { const el=$('#toast'); el.textContent=message; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); };

loadTraktDashboard();

async function loadTraktDashboard(){
  const dashboard=$('#trakt-dashboard');
  try{
    const response=await fetch('/api/trakt/dashboard');
    const data=await response.json();
    if(!response.ok)throw new Error(data.error);
    dashboard.innerHTML=`${!data.configured?`<div class="trakt-setup"><strong>Connect Trakt</strong><span>${escapeHTML(data.message||'Configure Trakt to load these shelves.')}</span></div>`:''}${(data.sections||[]).map(renderTraktSection).join('')}`;
  }catch(error){dashboard.innerHTML=`<div class="trakt-setup"><strong>Trakt is unavailable</strong><span>${escapeHTML(error.message)}</span></div>`;}
}

function renderTraktSection(section){
  const items=section.items||[];
  const status=section.locked?'Connect Trakt':section.error?'Unavailable':'';
  const cards=items.length?items.map(item=>{const detail=item.ids?.trakt&&['movie','show'].includes(item.mediaType)?`data-trakt-id="${escapeHTML(item.ids.trakt)}" data-trakt-type="${escapeHTML(item.mediaType)}" data-trakt-title="${escapeHTML(item.title)}" data-watchlisted="${item.watchlisted?'1':'0'}" data-season="${escapeHTML(item.season??'')}" data-episode="${escapeHTML(item.episode??'')}"`:'';const identifiers=[item.watchState==='watched'&&'<span class="poster-identifier watched">✓ Watched</span>',item.watchState==='in-progress'&&'<span class="poster-identifier progress">▶ In progress</span>',item.watchlisted&&'<span class="poster-identifier watchlist">＋ Watchlist</span>'].filter(Boolean).join('');return `<button class="trakt-card" ${detail} aria-label="View ${escapeHTML(item.title)} details">${item.image?`<img src="${escapeHTML(item.image)}" alt="" loading="lazy" draggable="false">`:''}<span class="trakt-shade"></span>${identifiers?`<span class="poster-identifiers">${identifiers}</span>`:''}<span class="trakt-card-copy"><b>${escapeHTML(item.title)}</b><small>${escapeHTML([item.calendarAt&&formatCalendarDate(item.calendarAt),item.year,item.rating&&`★ ${Number(item.rating).toFixed(1)}`].filter(Boolean).join(' · '))}</small></span>${item.progress!=null?`<progress class="trakt-progress" max="100" value="${Math.max(0,Math.min(100,Number(item.progress)||0))}"></progress>`:''}</button>`}).join(''):`<div class="trakt-placeholder"><span>${escapeHTML(section.error||status||'Nothing here yet')}</span></div>`;
  return `<section class="trakt-row"><div class="trakt-row-head"><h2>${escapeHTML(section.title)}</h2><div>${status?`<span>${escapeHTML(status)}</span>`:''}${items.length>0?`<button class="see-all" type="button">See all</button>`:''}</div></div><div class="trakt-strip">${cards}</div></section>`;
}

$('#trakt-dashboard').addEventListener('click',event=>{const expand=event.target.closest('.see-all');if(expand){const row=expand.closest('.trakt-row');row.classList.toggle('expanded');expand.textContent=row.classList.contains('expanded')?'Show less':'See all';return}const card=event.target.closest('[data-trakt-id]');if(card){if(suppressPosterClick){suppressPosterClick=false;return}openTraktDetails(card.dataset.traktType,card.dataset.traktId,card.dataset.season,card.dataset.episode)}});
function openPosterActions(card){posterActionItem={type:card.dataset.traktType,id:Number(card.dataset.traktId),title:card.dataset.traktTitle,watchlisted:card.dataset.watchlisted==='1',season:card.dataset.season,episode:card.dataset.episode};$('#poster-action-title').textContent=posterActionItem.title;$('#poster-watchlist-action').textContent=posterActionItem.watchlisted?'Remove from watchlist':'Add to watchlist';$('#poster-actions').showModal()}
$('#trakt-dashboard').addEventListener('pointerdown',event=>{const card=event.target.closest('.trakt-card[data-trakt-id]');if(!card)return;clearTimeout(posterHoldTimer);posterHoldTimer=setTimeout(()=>{suppressPosterClick=true;navigator.vibrate?.(30);openPosterActions(card)},550)});
